(() => {
  if (String(book.coverUrl || "")) return
  let html = java.get("detail")
  // let img = String(java.getString("$.img", html))
  // if (img) return desc

  let books = Array.from(
   org.jsoup.Jsoup.parse(html).select(".res-book-item")
  );
  let item = books.find(x => {
    let title = java.getString("h3@text", x)
    return title == book.name
  })

  if (item) return java.getString("a > img@src",item)
})()

ruleBookInfo.init:
@js:
if (String(book.name) && (!String(book.intro) || !book.coverUrl)) {
  let u = `https://www.qidian.com/so/${book.name}.html`
  let html = java.ajax(u);//java.log(html)
  if (/fffffffffffffffffff/.test(html)) {
    java.webView(null, u, "document.cookie")
    java.log("已更新cookie")
    html = java.ajax(u)
  }
  java.put("detail", html)
}; result

